import{_t as e,it as t,n,rt as r}from"./chunks/framework.BhEEDjPG.js";var i=JSON.parse(`{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"components/architecture.md","filePath":"components/architecture.md"}`),a={name:`components/architecture.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h1><h2 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to “Layers”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─ clients ──────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ widget.js (web, one &lt;script&gt;)  ·  your app (web view / native, docs/SDK-AUTH)   │</span></span>
<span class="line"><span>│ HTTPS + SSE · the client protocol (docs/CLIENT-PROTOCOL.md)                      │</span></span>
<span class="line"><span>└───────────────┬────────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>                ▼</span></span>
<span class="line"><span>┌─ packages/gateway ──────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ middleware: otel → cors → headers → gateway key → json → login (verified)        │</span></span>
<span class="line"><span>│ per turn:   shape+owner → rate limit → usage cap → ROUTE → run → meter → nudge   │</span></span>
<span class="line"><span>│ super agent (router.ts): one domain per turn — a Verdict choice over domain      │</span></span>
<span class="line"><span>│   cards: keywords → decision model → LLM; sticky; single-domain shortcut         │</span></span>
<span class="line"><span>│ media (upload ≠ attach) · voice (STT) · nudges (SSE) · health · metrics          │</span></span>
<span class="line"><span>└───────────────┬────────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>                ▼ runDomainAgent(domain, session, message)</span></span>
<span class="line"><span>┌─ packages/core ─────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ steps engine (pre-model): open ask? read in code → settle → chain → summary      │</span></span>
<span class="line"><span>│ prompt = identity + security preamble + capabilities + shared skills             │</span></span>
<span class="line"><span>│          + domain skills (typed: core + in-play type) + runtime facts            │</span></span>
<span class="line"><span>│ tool loop (≤ N rounds): set_type · guards (create gate, attested lists) · carry  │</span></span>
<span class="line"><span>│          → MCP call → draft (preview) · completion                               │</span></span>
<span class="line"><span>│ steps engine (post-model): late draw · summary card · redraw · dedupe · sanitize │</span></span>
<span class="line"><span>│ sessions · stores · trimming · llm chain · otel · logs                           │</span></span>
<span class="line"><span>└───────────────┬────────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>                ▼ stdio MCP, token + trace context in _meta</span></span>
<span class="line"><span>┌─ domains/&lt;name&gt; (your code) ────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ domain.json · skills/*.md · mcp/server.ts (validate/preview/create + internal_*) │</span></span>
<span class="line"><span>│ schema/*.json · steps/index.ts · mock/policy.ts · probe/ · evals/                │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>      ▲                                   ▲</span></span>
<span class="line"><span>      │ @marg-adk/verdict (typed decisions)   │ model chain: anthropic | openai-compatible | mock</span></span></code></pre></div><h2 id="one-turn-in-order" tabindex="-1">One turn, in order <a class="header-anchor" href="#one-turn-in-order" aria-label="Permalink to “One turn, in order”">​</a></h2><ol><li><strong>Gate.</strong> Shape and length; the session resolves (hydrated on a miss) and the caller must own it (404 otherwise); a finished chat is 409 unless post-create edits are allowed; rate limits (per session, per IP, in-flight); usage caps (plan tokens → a 429 with the reset). All before any SSE header is written.</li><li><strong>Route.</strong> One domain, no re-classification mid-journey or after completion.</li><li><strong>Steps first.</strong> If a runtime ask is open, the reply is read in code: settle (the draft is written, the next owed step or the summary is drawn in the same reply), skip, redraw, or words (the model answers with a runtime fact; the ask is drawn again under its answer). If the summary is up, &quot;Change something&quot; opens the review. A runtime turn costs no model call.</li><li><strong>The model.</strong> System prompt (cached prefix) + the runtime facts for this turn (step notes, media note, the open-ask note) + history + the new message; tools for the in-play type.</li><li><strong>Tools.</strong> Each call: the runtime&#39;s own <code>set_type</code>; <code>internal_*</code> refused; the attested-list guard; the carry rule (settled step values override the model&#39;s); the create gate (summary shown for THIS draft + a whole-content yes); the MCP call with the token in <code>_meta</code>; the draft updated from the arguments (merge on validate, replace on preview/create); completion detected on <code>created:true</code> + id. Back to the model.</li><li><strong>Finalize.</strong> Prose and ui blocks split (tolerant of fence junk); an owed step late-drawn under the reply with the model&#39;s own ask cut; the summary card when everything settled and the draft is valid; dedupe; the link scheme allowlist; the turn stored with its final blocks.</li><li><strong>After.</strong> Metered (plan tokens into caps; the usage ledger; the metering sink), the nudge re-armed, pending media attached once an id exists, <code>done</code> sent with usage.</li></ol><h2 id="state" tabindex="-1">State <a class="header-anchor" href="#state" aria-label="Permalink to “State”">​</a></h2><ul><li><strong>Session</strong> (persisted, token never): messages (windowed on turn boundaries and healed), usage, active domain and type, <code>preview</code> (the draft: slots, missing, refs, defaults, from-record, summary fingerprint, step states, edit state, identity), <code>shared</code> (media, scratch), completion.</li><li><strong>Draft</strong> = what the last validate/preview/create carried + runtime state. The pane and the summary render from it; the carry rule reads it; a change of identity resets dependent steps.</li><li><strong>Step state</strong> per key: asked (with the drawn block for reload) / settled (values, via, the settling message) / skipped.</li></ul><h2 id="where-things-run" tabindex="-1">Where things run <a class="header-anchor" href="#where-things-run" aria-label="Permalink to “Where things run”">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Where</th><th>Why</th></tr></thead><tbody><tr><td>Who may read a session</td><td>gateway (owner check)</td><td>a session id is an id, not a credential</td></tr><tr><td>Which domain</td><td>gateway router (Verdict)</td><td>typed decision, sticky, zero-cost with one domain</td></tr><tr><td>The system prompt</td><td>core (per domain × type, cached)</td><td>identical bytes keep provider caches warm</td></tr><tr><td>Reading a reply</td><td>core readers + the step&#39;s <code>read</code></td><td>whole-content rule, shared with evals</td></tr><tr><td>The create gate</td><td>core guard + the tool + the skill</td><td>three layers, never weakened</td></tr><tr><td>Validation</td><td>the domain&#39;s validate tool</td><td>the server may validate nothing</td></tr><tr><td>Uploads</td><td>gateway + the domain&#39;s <code>internal_*</code> tools</td><td>bytes never cross stdio as base64</td></tr><tr><td>Counters</td><td>Redis (or memory)</td><td>atomic windows across nodes</td></tr><tr><td>Sessions, ledgers</td><td>Mongo (or files)</td><td>durable, lazily hydrated</td></tr><tr><td>Traces, metrics, logs</td><td>OTLP → OpenObserve or any backend</td><td>one trace per turn across processes</td></tr></tbody></table><h2 id="entity-types-variants" tabindex="-1">Entity types (variants) <a class="header-anchor" href="#entity-types-variants" aria-label="Permalink to “Entity types (variants)”">​</a></h2><p>A domain may declare <code>types</code> (product lines, document kinds). The prompt then carries the core skill + only the in-play type&#39;s skill, and the tool list only that type&#39;s validate/preview/ create tools (plus common tools). The type is set from the opener&#39;s words, restored from the draft on resume, or by the model through the runtime-provided <code>set_type</code> tool; a switch resets the draft the way a form resets. Each type lists its own <code>steps</code> order and flags.</p><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/docs/ARCHITECTURE.md">docs/ARCHITECTURE.md</a> — edit it there; the site mirrors the repository.</small></p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};